import json
import pathlib

FILES = json.loads(r'''{"north_mcp/roles.sql":"-- PostgreSQL. Database roles the MCP server connects as, one per entitlement group.\n-- The server holds the credentials; a North user is mapped to exactly one role, or to none.\n-- Scope is enforced here, in the database, not by rewriting or inspecting the SQL.\n-- Throwaway passwords for local use only.\n\nCREATE ROLE north_desk_cad LOGIN PASSWORD 'localdev';   -- CAD desk: CAD rows only\nCREATE ROLE north_risk_all LOGIN PASSWORD 'localdev';   -- risk: every currency\n\nGRANT CONNECT ON DATABASE txn_dq TO north_desk_cad, north_risk_all;\nGRANT SELECT ON currencies, transactions, report_runs TO north_desk_cad, north_risk_all;\n\n-- Defaults that hold even if the server forgets to set them per transaction.\nALTER ROLE north_desk_cad SET default_transaction_read_only = on;\nALTER ROLE north_risk_all SET default_transaction_read_only = on;\nALTER ROLE north_desk_cad SET statement_timeout = '5s';\nALTER ROLE north_risk_all SET statement_timeout = '5s';\n\n-- CREATE TEMP TABLE is allowed inside a read-only transaction, so take it away.\nREVOKE TEMPORARY ON DATABASE txn_dq FROM PUBLIC;\n\n-- Row-level security keyed on the connected role. Nothing a query can set\n-- (set_config, SET ROLE) changes which role it is connected as.\nALTER TABLE transactions ENABLE ROW LEVEL SECURITY;\nCREATE POLICY desk_cad ON transactions FOR SELECT TO north_desk_cad USING (currency = 'CAD');\nCREATE POLICY risk_all ON transactions FOR SELECT TO north_risk_all USING (true);\nCREATE POLICY grader_all ON transactions FOR SELECT TO agent_ro USING (true);\n","north_mcp/access.example.json":"{\n  \"users\": {\n    \"cad.analyst@example.com\": \"north_desk_cad\",\n    \"risk.officer@example.com\": \"north_risk_all\"\n  }\n}\n","north_mcp/requirements.txt":"psycopg[binary]>=3.2,<4\nnorth-mcp-python-sdk @ git+https://github.com/cohere-ai/north-mcp-python-sdk.git\n","north_mcp/server.py":"\"\"\"MCP server for Cohere North: SQL access scoped to the calling North user.\n\n    python north_mcp/server.py\n\nBuilt on Cohere's north-mcp-python-sdk, which authenticates the request and exposes the\nuser's identity. All the access logic is in guard.py.\n\nSet NORTH_TRUSTED_ISSUERS (comma-separated) in any shared environment. Without it the\nSDK decodes the ID token without checking its signature, and the email claim that\nselects the database role could be forged.\n\"\"\"\n\nimport os\n\nfrom fastmcp.server.dependencies import get_access_token\nfrom north_mcp_python_sdk import NorthMCPServer\n\nimport guard\n\n_issuers = [s.strip() for s in os.environ.get(\"NORTH_TRUSTED_ISSUERS\", \"\").split(\",\") if s.strip()]\nmcp = NorthMCPServer(\"Governed SQL\", trusted_issuers=_issuers or None)\n\n\ndef _caller_email():\n    token = get_access_token()\n    return token.claims.get(\"email\") if token else None\n\n\n@mcp.tool()\ndef describe_access() -> dict:\n    \"\"\"Show which tables the current user can query and how their access is scoped.\n    Call this before writing SQL.\"\"\"\n    return guard.describe_access(_caller_email())\n\n\n@mcp.tool()\ndef run_query(sql: str) -> dict:\n    \"\"\"Run one read-only PostgreSQL SELECT as the current user and return the rows.\n    Rows the user is not entitled to are filtered out by the database.\"\"\"\n    return guard.run_query(_caller_email(), sql)\n\n\nif __name__ == \"__main__\":\n    mcp.run(transport=\"streamable-http\", port=int(os.environ.get(\"PORT\", \"5222\")))\n","north_mcp/guard.py":"\"\"\"Run agent-written SQL for a named user, inside that user's database scope.\n\nNo MCP or North code here, so it can be tested against PostgreSQL on its own.\n\n    identity (email)  ->  access map  ->  database role  ->  one read-only statement\n\nRules:\n  * A user who is not in the access map gets nothing (default deny).\n  * The query runs on a connection opened as the user's role. Row-level security and\n    grants in roles.sql decide what it can see; the SQL text is never inspected.\n  * One statement per call, in a read-only transaction that is rolled back, with a\n    statement timeout and a row cap.\n  * Every call is written to the audit log, including denied ones.\n\"\"\"\n\nimport hashlib\nimport json\nimport os\nimport time\nfrom datetime import date, datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import Path\n\nimport psycopg\n\nHERE = Path(__file__).resolve().parent\nACCESS_FILE = Path(os.environ.get(\"NORTH_MCP_ACCESS\", HERE / \"access.example.json\"))\nAUDIT_FILE = Path(os.environ.get(\"NORTH_MCP_AUDIT\", HERE / \"audit.jsonl\"))\nPG_HOST = os.environ.get(\"NORTH_MCP_PG_HOST\", \"localhost\")\nPG_PORT = os.environ.get(\"NORTH_MCP_PG_PORT\", \"5432\")\nPG_DB = os.environ.get(\"NORTH_MCP_PG_DB\", \"txn_dq\")\nROLE_PASSWORD = os.environ.get(\"NORTH_MCP_ROLE_PASSWORD\", \"localdev\")  # demo default\nTIMEOUT_MS = 5000\nMAX_ROWS = 200\n\nSCHEMA_DOC = \"\"\"PostgreSQL 16. Tables you may read:\n\ncurrencies(code CHAR(3) PRIMARY KEY, minor_units SMALLINT)\ntransactions(txn_id BIGINT PRIMARY KEY, external_ref VARCHAR(40), account_id VARCHAR(20),\n             currency CHAR(3), amount NUMERIC(18,4), posted_at TIMESTAMP  -- UTC,\n             value_date DATE  -- business date in America/Toronto,\n             reversal_of BIGINT, loaded_at TIMESTAMP  -- UTC)\nreport_runs(report_date DATE PRIMARY KEY, generated_at TIMESTAMP  -- UTC)\n\nOne read-only SELECT per call. At most {max_rows} rows are returned.\"\"\"\n\n\ndef _access_map():\n    return json.loads(ACCESS_FILE.read_text())[\"users\"]\n\n\ndef role_for(email):\n    \"\"\"Return the database role for this user, or None.\"\"\"\n    if not email or not isinstance(email, str):\n        return None\n    return _access_map().get(email.strip().lower())\n\n\ndef _audit(entry):\n    entry = {\"ts\": datetime.now(timezone.utc).isoformat(timespec=\"milliseconds\"), **entry}\n    with AUDIT_FILE.open(\"a\", encoding=\"utf-8\") as fh:\n        fh.write(json.dumps(entry) + \"\\n\")\n\n\ndef _json_value(value):\n    if isinstance(value, Decimal):\n        return str(value)\n    if isinstance(value, (date, datetime)):\n        return value.isoformat()\n    if isinstance(value, (bytes, memoryview)):\n        return bytes(value).hex()\n    return value\n\n\ndef _execute(role, sql):\n    \"\"\"Return (columns, rows, truncated). Raises psycopg.Error.\"\"\"\n    conninfo = psycopg.conninfo.make_conninfo(\n        host=PG_HOST, port=PG_PORT, dbname=PG_DB, user=role, password=ROLE_PASSWORD\n    )\n    with psycopg.connect(conninfo) as conn:\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\"SET TRANSACTION READ ONLY\")\n                cur.execute(f\"SET LOCAL statement_timeout = {TIMEOUT_MS}\")\n                # prepare=True sends the query with the extended protocol, which refuses\n                # more than one statement. Without it \"COMMIT; ...\" would end the\n                # read-only transaction and drop the timeout.\n                cur.execute(sql, prepare=True)\n                if cur.description is None:\n                    raise ValueError(\"statement returned no result set\")\n                columns = [col.name for col in cur.description]\n                rows = cur.fetchmany(MAX_ROWS + 1)\n                truncated = len(rows) > MAX_ROWS\n                return columns, rows[:MAX_ROWS], truncated\n        finally:\n            conn.rollback()\n\n\ndef run_query(email, sql):\n    \"\"\"Run one SELECT as the given user. Always returns a dict and always audits.\"\"\"\n    started = time.monotonic()\n    sql = (sql or \"\").strip().rstrip(\";\").strip()\n    role = role_for(email)\n    entry = {\n        \"tool\": \"run_query\",\n        \"user\": email,\n        \"role\": role,\n        \"sql\": sql,\n        \"sql_sha256\": hashlib.sha256(sql.encode()).hexdigest()[:16],\n    }\n\n    def finish(result):\n        entry.update(\n            status=result[\"status\"],\n            rows=result.get(\"row_count\", 0),\n            error=result.get(\"error\"),\n            ms=round((time.monotonic() - started) * 1000),\n        )\n        _audit(entry)\n        return result\n\n    if role is None:\n        return finish({\"status\": \"denied\", \"error\": \"no data access is configured for this user\"})\n    if not sql:\n        return finish({\"status\": \"error\", \"error\": \"empty query\"})\n    try:\n        columns, rows, truncated = _execute(role, sql)\n    except psycopg.Error as exc:\n        return finish({\"status\": \"error\", \"error\": str(exc).strip().splitlines()[0]})\n    except ValueError as exc:\n        return finish({\"status\": \"error\", \"error\": str(exc)})\n    return finish({\n        \"status\": \"ok\",\n        \"columns\": columns,\n        \"rows\": [[_json_value(v) for v in row] for row in rows],\n        \"row_count\": len(rows),\n        \"truncated\": truncated,\n    })\n\n\ndef describe_access(email):\n    \"\"\"Tell the agent what this user can query, so it does not have to guess.\"\"\"\n    role = role_for(email)\n    _audit({\"tool\": \"describe_access\", \"user\": email, \"role\": role,\n            \"status\": \"ok\" if role else \"denied\"})\n    if role is None:\n        return {\"status\": \"denied\", \"error\": \"no data access is configured for this user\"}\n    return {\"status\": \"ok\", \"role\": role, \"schema\": SCHEMA_DOC.format(max_rows=MAX_ROWS),\n            \"note\": \"Rows outside your entitlement are filtered out by the database. \"\n                    \"A total you compute covers only the rows you are allowed to see.\"}\n","north_mcp/prove.py":"\"\"\"Prove the guard blocks what it claims to block, each for its own reason.\n\n    python north_mcp/prove.py\n\nNeeds only PostgreSQL from docker compose; no North tenant, no model, no API key.\nA check passes only when the query fails with the expected error text, so a connection\nproblem or a typo can never count as \"blocked\".\n\"\"\"\n\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"eval\"))\n\nimport guard\nfrom tasks import TASKS\n\nCAD = \"cad.analyst@example.com\"\nRISK = \"risk.officer@example.com\"\nSTRANGER = \"someone.else@example.com\"\n\nfailures = []\n\n\ndef check(name, ok, detail=\"\"):\n    print(f\"{'ok  ' if ok else 'FAIL'} {name}{'  ' + str(detail) if detail else ''}\")\n    if not ok:\n        failures.append(name)\n\n\ndef blocked(name, email, sql, expected_error):\n    result = guard.run_query(email, sql)\n    error = result.get(\"error\") or \"\"\n    check(name, result[\"status\"] != \"ok\" and expected_error in error, error or \"query succeeded\")\n\n\ndef scalar(email, sql):\n    result = guard.run_query(email, sql)\n    if result[\"status\"] != \"ok\":\n        raise RuntimeError(f\"{sql!r} failed: {result.get('error')}\")\n    return result[\"rows\"][0][0]\n\n\ndef main():\n    audit_before = sum(1 for _ in guard.AUDIT_FILE.open()) if guard.AUDIT_FILE.exists() else 0\n    calls = 0\n\n    print(\"-- identity\")\n    for label, email in ((\"unknown user\", STRANGER), (\"missing identity\", None), (\"empty identity\", \"\")):\n        result = guard.run_query(email, \"SELECT 1\")\n        calls += 1\n        check(f\"{label} is denied before the database is touched\", result[\"status\"] == \"denied\",\n              result.get(\"error\"))\n\n    print(\"-- row scope\")\n    risk_cad = scalar(RISK, \"SELECT count(*) FROM transactions WHERE currency = 'CAD'\")\n    risk_all = scalar(RISK, \"SELECT count(*) FROM transactions\")\n    desk_all = scalar(CAD, \"SELECT count(*) FROM transactions\")\n    desk_other = scalar(CAD, \"SELECT count(*) FROM transactions WHERE currency <> 'CAD'\")\n    desk_distinct = guard.run_query(CAD, \"SELECT DISTINCT currency FROM transactions\")[\"rows\"]\n    calls += 5\n    check(\"risk role sees more than CAD\", risk_all > risk_cad > 0, f\"{risk_all} rows, {risk_cad} CAD\")\n    check(\"CAD desk sees every CAD row\", desk_all == risk_cad, f\"{desk_all} of {risk_cad}\")\n    check(\"CAD desk sees no other currency\", desk_other == 0 and desk_distinct == [[\"CAD\"]],\n          f\"{desk_other} rows, currencies {desk_distinct}\")\n    same_question = \"SELECT sum(amount) FROM transactions\"\n    check(\"same question, different answer per user\", scalar(CAD, same_question) != scalar(RISK, same_question))\n    calls += 2\n\n    print(\"-- attempts to widen scope\")\n    blocked(\"SET ROLE to the wider role\", CAD, \"SET ROLE north_risk_all\", \"permission denied\")\n    blocked(\"set_config('role') inside a SELECT\", CAD,\n            \"SELECT set_config('role', 'north_risk_all', false)\", \"permission denied\")\n    blocked(\"second statement after RESET ROLE\", CAD,\n            \"RESET ROLE; SELECT count(*) FROM transactions\", \"multiple commands\")\n    calls += 3\n\n    print(\"-- guards\")\n    blocked(\"writes are rejected\", RISK, \"DELETE FROM transactions\", \"read-only\")\n    blocked(\"COMMIT then write is rejected\", RISK, \"COMMIT; DELETE FROM transactions\", \"multiple commands\")\n    blocked(\"COMMIT then slow query is rejected\", RISK, \"COMMIT; SELECT pg_sleep(30)\", \"multiple commands\")\n    blocked(\"slow queries time out\", RISK, \"SELECT pg_sleep(30)\", \"statement timeout\")\n    blocked(\"answer key is not readable\", RISK, \"SELECT * FROM expected_issues\", \"permission denied\")\n    blocked(\"check results are not readable\", RISK, \"SELECT * FROM dq_results\", \"permission denied\")\n    blocked(\"password hashes are not readable\", RISK, \"SELECT * FROM pg_authid\", \"permission denied\")\n    blocked(\"temp tables cannot be created\", RISK, \"CREATE TEMP TABLE t AS SELECT 1\", \"permission denied\")\n    calls += 8\n    big = guard.run_query(RISK, \"SELECT generate_series(1, 100000)\")\n    calls += 1\n    check(\"large results are capped and flagged\",\n          big[\"status\"] == \"ok\" and big[\"row_count\"] == guard.MAX_ROWS and big[\"truncated\"] is True,\n          f\"{big.get('row_count')} rows, truncated={big.get('truncated')}\")\n\n    print(\"-- still useful\")\n    ok_refs = 0\n    for task in TASKS:\n        result = guard.run_query(RISK, task[\"reference\"])\n        calls += 1\n        ok_refs += result[\"status\"] == \"ok\" and result[\"row_count\"] > 0\n    check(\"all reference queries from eval/ run for the full-scope user\",\n          ok_refs == len(TASKS), f\"{ok_refs} of {len(TASKS)}\")\n\n    print(\"-- audit\")\n    lines = guard.AUDIT_FILE.read_text().splitlines()[audit_before:]\n    check(\"every call was audited, including denied ones\", len(lines) == calls,\n          f\"{len(lines)} entries for {calls} calls\")\n    check(\"denied calls record who asked\", any('\"status\": \"denied\"' in line and STRANGER in line for line in lines))\n\n    print(f\"\\n{len(failures)} failed checks\")\n    return 1 if failures else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",".gitignore":"eval/__pycache__/\nnorth_mcp/__pycache__/\nnorth_mcp/audit.jsonl\n"}''')
PATCHES = json.loads(r'''[["eval/harness.py","                    cur.execute(sql)\n                    if cur.description is None:","                    # prepare=True uses the extended protocol, which refuses more than one\n                    # statement; otherwise \"COMMIT; ...\" would escape the timeout.\n                    cur.execute(sql, prepare=True)\n                    if cur.description is None:"],["eval/harness.py","    check(\"slow queries time out\", \"statement timeout\" in (err or \"\"), err or \"no timeout\")\n","    check(\"slow queries time out\", \"statement timeout\" in (err or \"\"), err or \"no timeout\")\n    _, err = run_sql(\"COMMIT; SELECT pg_sleep(30)\")\n    check(\"a second statement is rejected\", \"multiple commands\" in (err or \"\"), err or \"both statements ran\")\n"],["docker-compose.yml","      - ./eval/agent_role.sql:/docker-entrypoint-initdb.d/05_agent_role.sql:ro\n","      - ./eval/agent_role.sql:/docker-entrypoint-initdb.d/05_agent_role.sql:ro\n      - ./north_mcp/roles.sql:/docker-entrypoint-initdb.d/06_north_roles.sql:ro\n"]]''')

for name, content in FILES.items():
    path = pathlib.Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
    print('wrote', name, len(content))
for name, old, new in PATCHES:
    path = pathlib.Path(name)
    text = path.read_text()
    assert text.count(old) == 1, (name, old)
    path.write_text(text.replace(old, new))
    print('patched', name)
